contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val) public payable {
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        uint stored = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(stored == val);
    }

    receive() external payable {}
}

